function Local() {
  let contador = 0;
  return (
    <section>
      <output>{contador}</output>
      <button onClick={() => { contador++; }}>+1</button>
    </section>
  );
}

import { useState } from "react";

function Contador() {
  const [n, setN] = useState(0);   // valor actual y función para cambiarlo
  return (
    <section>
      <output>{n}</output>
      <button onClick={() => setN(n + 1)}>+1</button>
    </section>
  );
}

function Despacho() {
  const [bultos, setBultos] = useState(0);
  return (
    <section>
      <Total bultos={bultos} />
      <Botones onSuma={() => setBultos(b => b + 5)} />
    </section>
  );
}

function Total({ bultos }) { return <b>{bultos}</b>; }
function Botones({ onSuma }) { return <button onClick={onSuma}>+5</button>; }
